# independent factor construction by explicit reversal
def explicit_factors(core_paths):
    edges=sorted({s.canonical(a,b) for p in core_paths for a,b in zip(p,p[1:])})
    idx={e:i for i,e in enumerate(edges)}
    m=len(edges)
