            else:
                q=list(reversed(p)); pos=len(p)-1-j; cnt=c
            assert q[pos]==u and q[pos+1]==v
            if pos==0: L=0
            else: L=type_of(q[pos-1],u)
            if pos+2==len(q): R=2
            else: R=type_of(v,q[pos+2])
            occs[ci].append((L,R,cnt))
            if isinstance(L,tuple): scopes[ci].add(L[0])
            if isinstance(R,tuple): scopes[ci].add(R[0])
    factors=[]
    for i in range(m):
        vars=(i,)+tuple(sorted(scopes[i]-{i}))
