                if st[0]==G[ls][rs]: total+=cnt
            vals[flat]=total
        factors.append((vars,vals))
    return edges,scopes,occs,factors

def brute(factors, edges, evidence=None):
    m=len(edges); idx={e:i for i,e in enumerate(edges)}
    # brute all assignments map var->state
